{
  "critique": [
    {
      "design": "r1A",
      "good": "CVE IDs and package names stay on one line, and the version column gives constraints room to form readable groups. The wider summary keeps rows shorter than in the other designs.",
      "problems": "The initial viewport shows almost none of the affected versions and none of the severity or summary. The tall rows also leave large empty areas under the identifiers, making comparison down the table laborious. The full table requires substantial horizontal scrolling.",
      "cause": "The 146px CVE and 183px package columns consume 329px before versions begin. The 320px summary reduces wrapping but contributes substantially to the 870px total width."
    },
    {
      "design": "r1B",
      "good": "Identifiers and package names remain intact, and the narrower table reduces horizontal scrolling. Version tokens remain intact despite wrapping.",
      "problems": "The initial view still reveals little of the version column. Constraints are broken into more lines, making each range harder to read as a unit. Very tall rows and extensive blank space in the first columns weaken the visual connection between adjacent advisories.",
      "cause": "The 105px version column leaves 84px for text, while the 241px summary leaves only 220px; together they increase wrapping, with the summary driving much of the row height."
    },
    {
      "design": "r1C",
      "good": "More of the version column appears on first sight, package names remain intact, and the 140px version column keeps related constraints more compact than in r1B.",
      "problems": "Every CVE ID wraps across two lines, making identifiers harder to scan and copy mentally. Severity and most version information still require scrolling, while tall summary-driven rows leave large blank areas beside the shorter cells.",
      "cause": "The 105px CVE column provides only 84px of text width, below the 125px needed for a one-line ID. The 300px summary limits some wrapping but still produces tall rows and contributes to the 809px overall width."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "balanced-readable",
      "widths": [146, 183, 140, 80, 280],
      "change": "Refine r1A by reducing the summary to 280px. This preserves complete IDs, package names and compact version groups while modestly reducing horizontal scrolling; the summary still has room for natural word wrapping."
    },
    {
      "name": "compact-versions",
      "widths": [146, 183, 120, 80, 300],
      "change": "Keep identifiers and packages intact, give versions a middle width between r1A and r1B, and retain a generous summary. This tests whether a small reduction in scrolling can be achieved without fragmenting version ranges as much as r1B."
    },
    {
      "name": "viewport-priority",
      "widths": [105, 160, 140, 80, 300],
      "change": "Explore a narrower first pair so more of the version column appears initially. CVE IDs will wrap at hyphens and the longest package path may wrap, but the version and summary columns retain readable widths."
    }
  ]
}
